"""Generate/check the fixed frontend projection from reviewed package metadata."""

import argparse
import json
from pathlib import Path

from archimind.assets.render_assets import product_projection


def registry_source() -> str:
    return (
        "// Generated by scripts/build_product_registry.py; do not hand edit.\n"
        "const freeze=o=>{Object.values(o).forEach(v=>{if(v&&typeof v==='object')freeze(v);});return Object.freeze(o);};\n"
        "export const PRODUCT_ASSETS=freeze("
        + json.dumps(product_projection(), sort_keys=True, separators=(",", ":"))
        + ");\n"
    )


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    path = (
        Path(__file__).resolve().parents[1]
        / "frontend/realistic_viewer/src/product_registry.js"
    )
    content = registry_source()
    if args.check:
        if path.read_text() != content:
            raise SystemExit("Product registry projection is stale")
    else:
        path.write_text(content)
